import type { Context } from "hono";
import { badRequest, internalError } from "@/lib/errors";
import { created, success } from "@/lib/response";
import { getIdempotencyRecordKey } from "@/middleware/idempotency";
import {
  createFireblocksCsr,
  discoverFireblocksVaults,
  getPendingFireblocksCsr,
} from "@/services/custody/fireblocks-registration.service";
import type { Env } from "@/types/env";
import { discoverFireblocksVaultsSchema } from "./schemas";

type AppContext = Context<{ Bindings: Env }>;

/** Only public CSR data crosses this boundary. Private keys are generated by the API. */
export async function getCsr(c: AppContext) {
  return success(c, { csr: await getPendingFireblocksCsr(c) });
}

export async function createCsr(c: AppContext) {
  const idempotencyKey = getIdempotencyRecordKey(c);
  if (!idempotencyKey) throw internalError();
  return created(c, { csr: await createFireblocksCsr(c, idempotencyKey) });
}

export async function discoverVaults(c: AppContext) {
  const body = discoverFireblocksVaultsSchema.safeParse(await c.req.json().catch(() => null));
  if (!body.success) throw badRequest("Invalid vault discovery request");
  c.header("Cache-Control", "no-store");
  return success(c, await discoverFireblocksVaults(c, body.data));
}
